-- +goose Up
-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.91.0',
  '2026-09-18',
  'Пульт ТВ: админка медиатеки, «обновить» и выбор музыки в плеере',
  E'В шапке медиатеки на ТВ два новых значка. «🔄 Обновить» подтягивает свежие данные: залили новый сериал — он появится без перезапуска страницы. «⚙ Админка» — управление медиатекой, закрыта PIN-кодом (его спросят один раз на устройстве).\n\nВ админке видно всё: сериалы, фильмы, видеоролики, фото и музыку с настоящим расположением на компьютере и размером. Можно переименовать (постер и место в «Продолжить просмотр» переезжают вместе с названием), зайти внутрь и удалить сериал целиком, сезон или отдельную серию. Удалённое не пропадает сразу: три дня лежит в корзине, оттуда его можно вернуть, потом стирается с диска само — о переносе в корзину и о стирании придёт сообщение в Telegram. Ещё там можно найти постер заново, посмотреть свободное место на дисках, почистить кэш копий фото, повторить поиск ненайденных постеров, очистить «Продолжить просмотр» и отправить себе проверочное уведомление.\n\nПод фильмом в панели музыки теперь можно выбрать музыкальную папку прямо там: раньше, если музыку не выбрали в каталоге, играть было нечего. Пока музыка не выбрана, список папок открыт сам; сменить — кнопкой «🎵 Выбрать». Кнопка адреса в приложении стала «🌐 Адрес», чтобы не путать её с шестерёнкой админки.',
  E'Прод: POST /api/v1/tv/notify {room, text} вне tma-авторизации, как веб-сокет приставки: пропуск — ключ комнаты, пишет только владельцу комнаты (TVRoomOwner), с «📺» и не больше 30 сообщений в час на комнату (tvNotifyLimiter, скользящее окно в памяти), текст обрезается до 1500 знаков; комната не закреплена — 404. Агент зовёт его сам (адрес выводится из шины: wss→https, /socket→/notify), страница на ТВ для этого не нужна.\n\nАгент (admin.go): /api/admin/* за заголовком X-Admin-Pin (admin_pin в конфиге; нет — админка выключена, 403 disabled), пять неверных подряд — пауза 5 минут. overview (библиотеки со Statfs и разделы buildCatalog с путями и размерами), children (всё в папке, кроме скрытого), rename (на диске, у файла расширение сохраняется, постер-сосед едет следом, записи progress переписываются: Dir/Rel по префиксу, ключ и id пересчитает resolve), delete → корзина <корень библиотеки>/.habits-trash/<id>/ (тот же диск — мгновенно; постер-сосед туда же; сбой посередине откатывается), trash.json в кэше, restore не затирает появившееся на старом месте, purge и trashWorker раз в 30 минут стирают истёкшее (trash_days, по умолчанию 3), poster/reset, service (кэш фото, *.miss, transcoded, progress, тест уведомления). Каталог вынесен в buildCatalog — у админки та же раскладка. Пустая корзина отдаётся [], а не null (поймано в браузере: список не рисовался).\n\nСтраница: значки «обновить» (перечитывает каталог, открытый сериал/папку фото/папку «Файлов»; удалённое — возврат на главную; играющее видео не трогается) и «админка» в шапке. Админка — отдельный слой #admin: PIN-клавиатура стрелками (и цифрами), вкладки Медиатека/Корзина/Обслуживание, вложенные папки, свои окна подтверждения и ввода вместо системных диалогов (в WebView на ТВ они блокируют страницу); в поле ввода Backspace и стрелки влево-вправо принадлежат полю, Enter — сохранить, Escape — отмена. Отрисовки нумеруются: опоздавший ответ прошлой вкладки не рисует поверх. Закрыли админку после изменений — каталог обновляется сам. В панели музыки плеера #mpick — папки музыки кнопками; идёт фильм — только выбрать, видео стоит — играть.\n\nПроверено: admin_test.go (PIN и пауза, имена, переименование сериала с постером и записью «Продолжить просмотр», фильм с сохранением расширения, отказы на занятое имя и корень, корзина с возвратом и стиранием, конфликт при возврате, пустая корзина, адрес уведомлений), тест лимита на проде, локальный агент в браузере с фейковым продом (все три уведомления дошли), после выкладки — проверочное уведомление с res-i3 через прод.'
);
-- +goose StatementEnd

